mapper.select:
SELECT COUNT(*)
FROM members m JOIN member_details d ON m.member_id = d.member_id
WHERE m.status = 0
  AND m.member_id != #{memberId}
  AND REGEXP_REPLACE(d.phone, '[^0-9]', '') = #{phone}

mapper.update:
UPDATE member_details d SET profile = #{profile, jdbcType=VARCHAR}
WHERE d.member_id = #{memberId}
  AND EXISTS (
      SELECT 1
      FROM members m
      WHERE m.member_id = d.member_id
        AND m.status = 0
  )

UPDATE members SET password = #{pwd}, fail_cnt = 0, blocked_until = NULL
WHERE member_id = #{memberId}
  AND status = 0

mapper.delete:
DELETE FROM sub_task_members stm
WHERE EXISTS (
    SELECT 1
    FROM project_members pm
    JOIN projects p ON p.project_id = pm.project_id
    WHERE stm.project_member_id = pm.project_member_id
      AND pm.workspace_member_id = #{workMemberId}
      AND p.workspace_id = #{workId}
)

DELETE FROM task_members tm
WHERE EXISTS (
    SELECT 1
    FROM project_members pm
    JOIN projects p ON p.project_id = pm.project_id
    WHERE tm.project_member_id = pm.project_member_id
      AND pm.workspace_member_id = #{workMemberId}
      AND p.workspace_id = #{workId}
)

mapper.update:
UPDATE project_members pm SET status = 1, "LEFT" = SYSDATE, updated = SYSDATE
WHERE pm.workspace_member_id = #{workMemberId}
  AND pm.status = 0
  AND EXISTS (
      SELECT 1
      FROM projects p
      WHERE p.project_id = pm.project_id
        AND p.workspace_id = #{workId}
  )

UPDATE workspace_members wm SET status = 1, "LEFT" = SYSDATE
WHERE wm.workspace_member_id = #{workMemberId}
  AND wm.workspace_id = #{workId}
  AND wm.member_id = #{memberId}
  AND wm.status = 0
  AND wm.role != 70

  AND EXISTS (
      SELECT 1
      FROM workspaces w
      JOIN workspace_domains wd ON wd.workspace_id = w.workspace_id
      WHERE w.workspace_id = wm.workspace_id
        AND w.member_id != #{memberId}
        AND wd.active = 'Y'
  )

mapper.select:
SELECT cr.chat_room_id chatRoomId, cr.workspace_member_id chatOwnerMemberId,
    cr.chat, crm.chat_room_member_id chatRoomMemberId, crm.status chatRoomMemberStatus
FROM chat_rooms cr

JOIN workspace_members owner ON owner.workspace_member_id = cr.workspace_member_id

LEFT JOIN chat_room_members crm ON crm.chat_room_id = cr.chat_room_id
 AND crm.workspace_member_id = #{workMemberId}

WHERE owner.workspace_id = #{workId}
  AND (
  	crm.status = 0
      OR (
          cr.chat = 'GROUP'
          AND cr.workspace_member_id = #{workMemberId}
      )
  )
ORDER BY cr.chat_room_id

SELECT cr.chat_room_id chatRoomId, cr.workspace_member_id chatOwnerMemberId,
    cr.chat, crm.chat_room_member_id chatRoomMemberId, crm.status chatRoomMemberStatus
FROM chat_rooms cr

JOIN workspace_members owner ON owner.workspace_member_id = cr.workspace_member_id

LEFT JOIN chat_room_members crm ON crm.chat_room_id = cr.chat_room_id
 AND crm.workspace_member_id = #{workMemberId}

WHERE cr.chat_room_id = #{chatRoomId}
  AND owner.workspace_id = #{workId}
  AND (
      crm.status = 0
      OR (
          cr.chat = 'GROUP'
          AND cr.workspace_member_id = #{workMemberId}
      )
  )

mapper.update:
UPDATE chat_rooms cr SET workspace_member_id = #{chatTargetMemberId}

WHERE cr.chat_room_id = #{chatRoomId}
  AND cr.chat = 'GROUP'
  AND cr.workspace_member_id = #{workMemberId}
  AND #{chatTargetMemberId} != #{workMemberId}

  AND EXISTS (
      SELECT 1
      FROM chat_room_members crm

      JOIN workspace_members wm ON wm.workspace_member_id = crm.workspace_member_id

      JOIN members m ON m.member_id = wm.member_id

      WHERE crm.chat_room_id = cr.chat_room_id
        AND crm.workspace_member_id = #{chatTargetMemberId}
        AND crm.status = 0
        AND wm.status = 0
        AND wm.workspace_id = #{workId}
        AND m.status = 0
  )

	UPDATE chat_room_members crm SET status = 1, "LEFT" = SYSDATE

    WHERE crm.chat_room_id = #{chatRoomId}
      AND crm.workspace_member_id = #{workMemberId}
      AND crm.status = 0

      AND EXISTS (
          SELECT 1
          FROM chat_rooms cr

          JOIN workspace_members owner ON owner.workspace_member_id = cr.workspace_member_id

          WHERE cr.chat_room_id = crm.chat_room_id 
          	AND owner.workspace_id = #{workId}
      )

mapper.insert:
INSERT INTO chat_messages (message_id, chat_room_id, chat_room_member_id,
    content, message_type, sent)

SELECT seq_chat_messages.NEXTVAL, cr.chat_room_id, crm.chat_room_member_id,
    #{systemMessage, jdbcType=CLOB}, 'SYSTEM', SYSDATE
FROM chat_rooms cr

JOIN workspace_members owner ON owner.workspace_member_id = cr.workspace_member_id

JOIN chat_room_members crm ON crm.chat_room_id = cr.chat_room_id

WHERE cr.chat_room_id = #{chatRoomId}
  AND owner.workspace_id = #{workId}
  AND crm.chat_room_member_id = #{chatRoomMemberId}
  AND crm.workspace_member_id = #{workMemberId}

