DELETE FROM chat_messages cm
WHERE cm.chat_room_id = #{chatRoomId}

  AND EXISTS (
      SELECT 1
      FROM chat_rooms cr

      JOIN workspace_members owner ON owner.workspace_member_id = cr.workspace_member_id

      WHERE cr.chat_room_id = cm.chat_room_id
        AND owner.workspace_id = #{workId}
  )

DELETE FROM chat_room_members crm
WHERE crm.chat_room_id = #{chatRoomId}

  AND EXISTS (
      SELECT 1
      FROM chat_rooms cr
      JOIN workspace_members owner ON owner.workspace_member_id = cr.workspace_member_id
      WHERE cr.chat_room_id = crm.chat_room_id
        AND owner.workspace_id = #{workId}
  )
